import torch

_DST_TYPE_MAP = {"int4": torch.quint4x2, "int8": torch.int8}

def run(x, smooth_scales=None, offsets=None, group_index=None, activate_left=False, quant_mode=0, group_list_type=0, dst_type=None):
    if isinstance(dst_type, str):
        dst_type = _DST_TYPE_MAP.get(dst_type, dst_type)
    if dst_type is None:
        dst_type = torch.int8

    is_int4 = (dst_type == torch.quint4x2)
    dst_scale = 7.0 if is_int4 else 127.0

    x1, x2 = torch.chunk(x, 2, dim=-1)
    x1f = x1.float()
    x2f = x2.float()
    if activate_left:
        y = torch.nn.functional.silu(x1f) * x2f
    else:
        y = x1f * torch.nn.functional.silu(x2f)

    y_last_dim = y.shape[-1]
    batch_dim = x.shape[0]

    if group_index is not None:
        begin_index = 0
        for i in range(group_index.shape[0]):
            end_index = group_index[i].item() if group_list_type == 0 else begin_index + group_index[i].item()
            end_index = min(end_index, batch_dim)
            if end_index <= begin_index:
                begin_index = end_index
                continue
            y_slice = y[begin_index:end_index]
            scale_slice = smooth_scales[i].float()
            if offsets is not None and quant_mode == 0:
                offset_slice = offsets[i].float()
            else:
                offset_slice = None

            if scale_slice.shape[-1] == y_last_dim:
                y[begin_index:end_index] = y_slice * scale_slice + (offset_slice if offset_slice is not None else 0)
            elif scale_slice.shape[-1] == batch_dim:
                token_scale = scale_slice[begin_index:end_index].unsqueeze(-1)
                if offset_slice is not None:
                    token_offset = offset_slice[begin_index:end_index].unsqueeze(-1)
                else:
                    token_offset = 0
                y[begin_index:end_index] = y_slice * token_scale + token_offset
            else:
                y[begin_index:end_index] = y_slice * scale_slice + (offset_slice if offset_slice is not None else 0)

            begin_index = end_index
    else:
        if smooth_scales is not None:
            if smooth_scales.shape[-1] == y_last_dim:
                y = y * smooth_scales.float()
            elif smooth_scales.shape[-1] == batch_dim:
                y = y * smooth_scales.float().unsqueeze(-1)
        if offsets is not None and quant_mode == 0:
            if offsets.shape[-1] == y_last_dim:
                y = y + offsets.float()
            elif offsets.shape[-1] == batch_dim:
                y = y + offsets.float().unsqueeze(-1)

    scale = None
    if quant_mode == 1:
        scale = dst_scale / torch.max(torch.abs(y), dim=1)[0]
        y = y * scale.unsqueeze(1)

    y = torch.round(y)
    y = torch.clamp(y, -1 - dst_scale, dst_scale)

    if is_int4:
        y_reshaped = y.reshape(*y.shape[:-1], -1, 2)
        low = (y_reshaped[..., 0].to(torch.int32) & 0xF).to(torch.uint8)
        high = (y_reshaped[..., 1].to(torch.int32) & 0xF).to(torch.uint8)
        y = ((high << 4) | low).to(torch.int8)
    else:
        y = y.to(torch.int8)

    if scale is None:
        scale = torch.zeros(x.shape[0], dtype=torch.float32, device=x.device)

    return y, scale
